document.addEventListener("DOMContentLoaded",function(){const s=document.getElementById("clothing-size-form"),e=document.getElementById("clothing-size-result");s.addEventListener("submit",function(s){s.preventDefault();const n=parseFloat(document.getElementById("bust").value),i=parseFloat(document.getElementById("underbust").value),t=parseFloat(document.getElementById("waist").value),u=parseFloat(document.getElementById("hips").value);if([n,i,t,u].some(s=>isNaN(s)||s<=0))return e.innerHTML="<p>Please enter valid measurements for all fields.</p>",void 0;if(n<=i)return e.innerHTML="<p>Bust measurement should be larger than underbust measurement.</p>",void 0;const a=function(s,e){const n=s-e;let i="";return i=n<10?"AA":n>=10&&n<12.5?"A":n>=12.5&&n<15?"B":n>=15&&n<17.5?"C":n>=17.5&&n<20?"D":n>=20&&n<22.5?"DD":n>=22.5&&n<25?"E":n>=25&&n<27.5?"F":n>=27.5&&n<30?"FF":"G",`${5*Math.round(e/5)}${i}`}(n,i),r=[{int:"XS",eu:"32",us:"0",uk:"4",bust:76,waist:58,hips:82},{int:"XS",eu:"34",us:"2",uk:"6",bust:80,waist:62,hips:86},{int:"S",eu:"36",us:"4",uk:"8",bust:84,waist:66,hips:90},{int:"S",eu:"38",us:"6",uk:"10",bust:88,waist:70,hips:94},{int:"M",eu:"40",us:"8",uk:"12",bust:92,waist:74,hips:98},{int:"M",eu:"42",us:"10",uk:"14",bust:96,waist:78,hips:102},{int:"L",eu:"44",us:"12",uk:"16",bust:100,waist:82,hips:106},{int:"L",eu:"46",us:"14",uk:"18",bust:104,waist:86,hips:110},{int:"XL",eu:"48",us:"16",uk:"20",bust:108,waist:90,hips:114},{int:"XL",eu:"50",us:"18",uk:"22",bust:112,waist:94,hips:118},{int:"XXL",eu:"52",us:"20",uk:"24",bust:116,waist:98,hips:122},{int:"XXL",eu:"54",us:"22",uk:"26",bust:120,waist:102,hips:126}];let l=null,o=1/0;for(const s of r){const e=Math.abs(n-s.bust),i=Math.abs(t-s.waist),a=Math.abs(u-s.hips);if(n<=s.bust+4&&t<=s.waist+4&&u<=s.hips+4){const n=e+i+a;n<o&&(o=n,l=s)}}l||(l=r[r.length-1]),e.innerHTML=a&&l?`\n        <div class="size-results">\n          <h3>🩱 Your Bra Size:</h3>\n          <div class="bra-size-result"><strong>${a}</strong></div>\n          \n          <h3>👗 Your Clothing Size:</h3>\n          <div class="clothing-sizes">\n            <div class="size-item"><strong>International:</strong> <span class="size-value">${l.int}</span></div>\n            <div class="size-item"><strong>European (EU):</strong> <span class="size-value">${l.eu}</span></div>\n            <div class="size-item"><strong>US:</strong> <span class="size-value">${l.us}</span></div>\n            <div class="size-item"><strong>UK:</strong> <span class="size-value">${l.uk}</span></div>\n          </div>\n          \n          <div class="measurement-note">\n            <h4>📏 Your Measurements:</h4>\n            <ul>\n              <li>Bust: ${n} cm</li>\n              <li>Underbust: ${i} cm</li>\n              <li>Waist: ${t} cm</li>\n              <li>Hips: ${u} cm</li>\n            </ul>\n          </div>\n          \n          <div class="size-advice">\n            <h4>💡 Shopping Tips:</h4>\n            <ul>\n              <li>Always check the specific brand's size chart when shopping online</li>\n              <li>For push-up bras, consider going down half a cup size</li>\n              <li>Consider the fit style (slim, regular, loose) when selecting clothing size</li>\n              <li>For stretchy fabrics, you might prefer a size smaller for a more fitted look</li>\n              <li>Read reviews about sizing and fit before purchasing</li>\n              <li>When in doubt between two sizes, consider your preferred fit and the garment type</li>\n            </ul>\n          </div>\n        </div>\n      `:`\n        <div class="no-match">\n          <h3>Custom Size Needed</h3>\n          <p>Your measurements don't match standard sizing exactly. Here are your options:</p>\n          <ul>\n            <li>Look for brands that offer custom sizing or extended size ranges</li>\n            <li>Consider professional bra fitting services</li>\n            <li>Check if the brand offers detailed size charts with exact measurements</li>\n            <li>Contact customer service for size recommendations</li>\n          </ul>\n          \n          <div class="measurement-summary">\n            <h4>Your Measurements:</h4>\n            <p>Bust: ${n} cm | Underbust: ${i} cm | Waist: ${t} cm | Hips: ${u} cm</p>\n          </div>\n        </div>\n      `})});